// ---------- Eras / genres ----------
// Every number in "settings" is a starting estimate based on rough historical averages.
// They are shown on the creation screen and can be changed by the user.

function occ(name, n, o) {
  o = o || {};
  return Object.assign({ id: name.toLowerCase().replace(/[^a-z0-9]+/g, '_'), name, n,
    sex: 'any', min: 16, cls: 'low', wp: 'own', place: null, boss: null, skill: 'labor',
    uses: [], produces: [], inherit: 0.3 }, o);
}

